func TestProtoV6ProviderFactories_ReturnsF5XCEntry(t *testing.T) {
	factories := ProtoV6ProviderFactories(t)

	if factories == nil {
		t.Fatal("ProtoV6ProviderFactories returned nil")
	}

	f5xcFactory, ok := factories["f5xc"]
	if !ok {
		t.Fatal("expected 'f5xc' key in provider factories map")
	}

	if f5xcFactory == nil {
		t.Fatal("expected non-nil factory function for 'f5xc'")
	}

	// Verify the factory can be called without error.
	server, err := f5xcFactory()
	if err != nil {
		t.Fatalf("f5xc provider factory returned error: %v", err)
	}
	if server == nil {
		t.Fatal("f5xc provider factory returned nil server")
	}
}

